const norm = $('Normalize Input').first().json || {};
const p = $('Check Pending').first().json || {};
const raw = String(norm.chatInput || '').trim();
const ans = raw.toLowerCase();

const offInt = [true, 'true', 1, '1'].includes(p.offered_internet);
const offNot = [true, 'true', 1, '1'].includes(p.offered_notify);
const question = p.question || '';

let action = 'decline';
if (ans === 'n' || ans === 'no') {
  action = 'decline';
} else if (ans.indexOf('1') >= 0 && offInt) {
  action = 'internet';
} else if (ans.indexOf('2') >= 0 && offNot) {
  action = 'notify';
} else if (ans === 'y' || ans === 'yes') {
  action = offInt ? 'internet' : (offNot ? 'notify' : 'decline');
} else {
  action = 'decline';
}

return [{ json: {
  action: action,
  question: question,
  session_id: p.session_id || norm.session_id,
  channel: norm.channel || p.channel || 'chat',
  reply_token: norm.reply_token || '',
} }];

