const emb = ((($('Embed Question').first() || {}).json || {}).embedding || {}).values || [];
const cfg = (($('Load Config').first() || {}).json) || {};

function cos(a, b) {
  if (!a || !b || !a.length || !b.length || a.length !== b.length) return -1;
  let d = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  if (na === 0 || nb === 0) return -1;
  return d / (Math.sqrt(na) * Math.sqrt(nb));
}

function cfgNum(v, fallback) {
  const n = Number(v);
  return (v === null || v === undefined || v === '' || !isFinite(n)) ? fallback : n;
