  const A = trigrams(a), B = trigrams(b);
  let inter = 0, ua = 0, ub = 0;
  for (const k in A) { ua++; if (B[k]) inter++; }
  for (const k in B) { ub++; }
  const uni = ua + ub - inter;
  return uni ? inter / uni : 0;
}
