    pieces.push(line.slice(0, MAX));
    line = line.slice(MAX);
  }
  const candidate = buf ? (buf + NL + line) : line;
  if (candidate.length > MAX) {
    if (buf) pieces.push(buf);
    buf = line;
  } else {
    buf = candidate;
  }
}
if (buf) pieces.push(buf);

const nonEmpty = [];
for (const p of pieces) {
  if (String(p || '').trim().length > 0) nonEmpty.push(p);
}
